from pathlib import Path

from fastapi import APIRouter

router = APIRouter()

FRONTEND_DIST = Path(__file__).resolve().parents[1] / "frontend" / "dist"

# The build directory is generated by Vite. check_dir=False lets the API run
# while the frontend is being developed separately with the Vite dev server.
router.frontend(
    "/",
    directory=FRONTEND_DIST,
    fallback="index.html",
    check_dir=False,
)